INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Ethan ordered a new phone online during a big sale. Two days later, the package arrived, but the box contained the wrong model. He contacted customer service immediately, and they agreed to send the correct phone overnight. Ethan received the right device the very next morning."}'::jsonb, '{"key_points": ["Ethan ordered a phone online", "the wrong model arrived", "customer service agreed to send the correct one overnight", "he received it the next morning"]}'::jsonb, 47, 0.55, 'B2', 'approved', 'exam', 'shopping', 'a3000000-0000-4000-8000-000000000016', 1),
('passage_reconstruction', '{"passage": "Priya had been saving for a new laptop for her design work. She compared several models online before visiting a local shop. The salesperson recommended one slightly above her budget but with better battery life. Priya decided it was worth the extra cost and bought it."}'::jsonb, '{"key_points": ["Priya saved for a laptop", "she compared models online", "the salesperson recommended a pricier one with better battery life", "she bought it anyway"]}'::jsonb, 46, 0.58, 'B2', 'approved', 'exam', 'technology', 'a3000000-0000-4000-8000-000000000016', 2);
